#pragma once
#include <string>
#include <cstdint>
#include "../common/types.h"
#include "../tiling/tiled_image.h"
#include "../tiling/provenance_map.h"

namespace unflatten {

// One editable layer (brief §26). UUID is a 128-bit value stored as two
// uint64s to avoid pulling in a UUID library; generated by the JNI bridge
// via Android's SecureRandom-backed java.util.UUID and passed in, or by the
// deterministic test-only generator in tests.
struct LayerId {
    uint64_t hi = 0, lo = 0;
    bool operator==(const LayerId& o) const { return hi == o.hi && lo == o.lo; }
    std::string toHexString() const;
    static LayerId fromHexString(const std::string& s);
};

// Generates a random 128-bit LayerId (std::random_device seeded, not
// cryptographically hardened -- layer IDs need only be locally unique
// within a project, not attacker-unpredictable). Used by the fallback
// pipeline and by tests; the JNI bridge instead accepts IDs generated by
// java.util.UUID on the Kotlin side when a layer is created interactively,
// so ID generation isn't duplicated across the JNI boundary.
LayerId newLayerId();

struct GenerationMetadata {
    std::string sourceModel;   // empty if not model-generated (this build never sets it)
    std::string modelVersion;
    std::string modelSha256;
    std::string generationPass; // e.g. "FALLBACK_HEURISTIC_SEGMENTATION_V1"
    int64_t seed = 0;
    bool hasSeed = false;
};

class Layer {
public:
    LayerId id{};
    std::string name;
    LayerType type = LayerType::Object;

    // RGBA content, cropped to compact bounds (not full canvas), per §26/§27.
    TiledImage rgba;
    // Visible (modal) mask and amodal (complete, possibly hidden-extending)
    // mask, both aligned to `rgba.bounds()`. Amodal mask defaults equal to
    // the visible mask until/unless a completion stage runs (§11).
    TiledImage visibleMask;
    TiledImage amodalMask;

    ProvenanceMap provenance; // same bounds as rgba

    float opacity = 1.0f;
    BlendMode blendMode = BlendMode::Normal;
    bool visible = true;
    bool locked = false;

    int32_t depthIndex = 0; // lower draws first (further back); see OcclusionGraph
    float offsetX = 0.0f, offsetY = 0.0f; // user transform, applied on top of bounds origin

    // Relationship links by LayerId (empty vector = none). Brief §14: shadows/
    // reflections stay independently editable but keep a soft link to a
    // likely parent.
    std::vector<LayerId> shadowOf;
    std::vector<LayerId> reflectionOf;

    GenerationMetadata generation;

    // Text-specific optional fields (brief §15); raster content in `rgba`
    // remains authoritative when these are empty (no font reconstruction
    // performed in this build -- OCR/text stage is NOT IMPLEMENTED, see
    // BUILD_REPORT.md).
    std::string recognizedText;
    bool hasRecognizedText = false;
};

} // namespace unflatten
